ALTER TABLE public.pesajes_cintas_lotes ADD COLUMN imp_bobina_id uuid REFERENCES public.imp_bobinas(id), ADD COLUMN planta_corte_id uuid REFERENCES public.plantas(id);
CREATE INDEX pcl_imp_bobina ON public.pesajes_cintas_lotes(imp_bobina_id) WHERE imp_bobina_id IS NOT NULL;
ALTER TABLE public.pesajes_cintas_lotes ADD CONSTRAINT pcl_imp_isolated CHECK (imp_bobina_id IS NULL OR (muestra_calidad_id IS NULL AND pesaje_bobina_madre_id IS NULL AND orden_produccion_id IS NULL AND producto_id IS NULL AND planta_corte_id IS NOT NULL));
CREATE OR REPLACE FUNCTION public.imp_asignar_sku(_id uuid,_sku text,_revision integer,_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.imp_bobinas; a jsonb; BEGIN IF NOT public.imp_permiso('editar') THEN RAISE EXCEPTION 'SKU solo Calidad y adgral' USING ERRCODE='42501'; END IF; IF length(btrim(coalesce(_sku,''))) NOT BETWEEN 1 AND 64 OR length(btrim(coalesce(_motivo,'')))<10 THEN RAISE EXCEPTION 'SKU y motivo de mínimo 10 caracteres obligatorios'; END IF; SELECT * INTO b FROM public.imp_bobinas WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Bobina no encontrada'; END IF; IF b.revision IS DISTINCT FROM _revision THEN RAISE EXCEPTION 'El registro cambió. Actualice antes de guardar.'; END IF; IF nullif(btrim(b.sku),'') IS NOT NULL THEN RAISE EXCEPTION 'El SKU ya fue asignado; utilice la edición autorizada de 36 horas.'; END IF; a:=to_jsonb(b); UPDATE public.imp_bobinas SET sku=btrim(_sku),revision=revision+1 WHERE id=_id RETURNING * INTO b; INSERT INTO public.imp_eventos(bobina_id,accion,usuario_id,motivo,antes,despues) VALUES(_id,'sku_asignado',auth.uid(),btrim(_motivo),a,to_jsonb(b)); RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.imp_asignar_sku(uuid,text,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.imp_asignar_sku(uuid,text,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.imp_proteger_sku() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.imp_permiso('editar') AND ((TG_OP='INSERT' AND nullif(btrim(NEW.sku),'') IS NOT NULL) OR (TG_OP='UPDATE' AND NEW.sku IS DISTINCT FROM OLD.sku)) THEN RAISE EXCEPTION 'SKU solo Calidad y adgral' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER imp_sku_autorizado BEFORE INSERT OR UPDATE ON public.imp_bobinas FOR EACH ROW EXECUTE FUNCTION public.imp_proteger_sku();
CREATE OR REPLACE FUNCTION public.imp_crear_lote_cintas(_id uuid,_conductor uuid,_bobinadora uuid,_idempotency uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.imp_bobinas; c public.operarios; m public.catalogo_bobinadoras; r public.rollos_cintas; n integer; lid uuid; rid uuid; snap jsonb; BEGIN PERFORM public._pc_require_access(auth.uid()); IF NOT public.can_edit_module(auth.uid(),'pesaje_cintas') THEN RAISE EXCEPTION 'Sin permiso para registrar cortes' USING ERRCODE='42501'; END IF; IF NOT public.imp_permiso('leer') THEN RAISE EXCEPTION 'Sin permiso de consulta importada' USING ERRCODE='42501'; END IF; SELECT * INTO b FROM public.imp_bobinas WHERE id=_id FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Bobina importada no encontrada'; END IF; IF nullif(btrim(b.sku),'') IS NULL THEN RAISE EXCEPTION 'necesita atención Calidad SKU'; END IF; IF coalesce((b.valores->>'peso_bobina')::numeric,0)<=0 THEN RAISE EXCEPTION 'Bobina importada sin peso de origen'; END IF; SELECT * INTO m FROM public.catalogo_bobinadoras WHERE id=_bobinadora AND activo; SELECT * INTO c FROM public.operarios WHERE id=_conductor AND activo; IF m.id IS NULL OR c.id IS NULL OR m.planta_id IS NULL OR c.planta_id IS DISTINCT FROM m.planta_id OR NOT public.user_sees_planta(auth.uid(),m.planta_id) THEN RAISE EXCEPTION 'Conductor y bobinadora deben pertenecer a su planta autorizada' USING ERRCODE='42501'; END IF; PERFORM pg_advisory_xact_lock(hashtext('rollo:'||b.folio)); SELECT id INTO lid FROM public.pesajes_cintas_lotes WHERE idempotency_key=_idempotency AND imp_bobina_id=_id AND creado_por=auth.uid(); IF lid IS NOT NULL THEN RETURN lid; END IF; SELECT * INTO r FROM public.rollos_cintas WHERE numero_rollo=b.folio; IF coalesce(r.cerrado,false) THEN RAISE EXCEPTION 'Rollo cerrado definitivamente'; END IF; IF EXISTS(SELECT 1 FROM public.pesajes_cintas_lotes WHERE numero_rollo=b.folio AND estado='abierto') THEN RAISE EXCEPTION 'Ya existe una bajada abierta para este rollo'; END IF; SELECT count(*) INTO n FROM public.pesajes_cintas_lotes WHERE numero_rollo=b.folio AND estado<>'anulado'; IF n>=7 THEN RAISE EXCEPTION 'Máximo de 7 bajadas'; END IF; rid:=public.pc_get_or_create_rollo(b.folio); snap:=jsonb_build_object('origen','importada','imp_bobina_id',b.id,'proveedor',b.proveedor_nombre,'sku',b.sku,'producto_codigo',b.producto_codigo,'turno',b.turno,'analista',b.analista,'estado',b.estado,'mediciones','{}'::jsonb,'bobina_snapshot',to_jsonb(b),'numero_bajada',n+1,'datos_origen',jsonb_build_object('origen','importada','imp_bobina_id',b.id,'peso_neto_origen_kg',b.valores->'peso_bobina','peso_origen','bobina_importada','planta_corte_id',m.planta_id)); INSERT INTO public.pesajes_cintas_lotes(imp_bobina_id,planta_corte_id,numero_rollo,fabricacion,producto_codigo,producto_nombre,fecha_produccion,conductor_id,conductor_nombre_snapshot,bobinadora_id,bobinadora_nombre_snapshot,peso_bobina_madre_neto_kg,peso_pendiente_kg,datos_calidad_snapshot,idempotency_key,creado_por,rollo_id,numero_bajada) VALUES(b.id,m.planta_id,b.folio,'MP-00',b.producto_codigo,b.producto_codigo,b.fecha,c.id,c.nombre,m.id,m.nombre,(b.valores->>'peso_bobina')::numeric,(b.valores->>'peso_bobina')::numeric,snap,_idempotency,auth.uid(),rid,n+1) RETURNING id INTO lid; INSERT INTO public.pesajes_cintas_auditoria(lote_id,accion,valores_nuevos,realizado_por) VALUES(lid,'LOTE_IMPORTADO_CREADO',snap,auth.uid()); RETURN lid; END $$;
REVOKE ALL ON FUNCTION public.imp_crear_lote_cintas(uuid,uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.imp_crear_lote_cintas(uuid,uuid,uuid,uuid) TO authenticated;
CREATE POLICY pcl_imp_planta ON public.pesajes_cintas_lotes AS RESTRICTIVE FOR SELECT TO authenticated USING(imp_bobina_id IS NULL OR public.user_sees_planta(auth.uid(),planta_corte_id));
CREATE OR REPLACE FUNCTION public.imp_cinta_datos() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.pesajes_cintas_lotes; BEGIN SELECT * INTO l FROM public.pesajes_cintas_lotes WHERE id=NEW.lote_id; IF l.imp_bobina_id IS NOT NULL THEN IF NOT public.user_sees_planta(auth.uid(),l.planta_corte_id) OR NOT public.can_edit_module(auth.uid(),'pesaje_cintas') THEN RAISE EXCEPTION 'Sin permiso para cortes de esta planta' USING ERRCODE='42501'; END IF; IF nullif(btrim(l.datos_calidad_snapshot->>'sku'),'') IS NULL THEN RAISE EXCEPTION 'necesita atención Calidad SKU'; END IF; IF NEW.sku_sap IS DISTINCT FROM l.datos_calidad_snapshot->>'sku' THEN IF TG_OP='UPDATE' OR (NEW.sku_sap IS NOT NULL AND NOT public.imp_permiso('editar')) THEN RAISE EXCEPTION 'SKU solo Calidad y adgral' USING ERRCODE='42501'; END IF; END IF; NEW.sku_sap:=l.datos_calidad_snapshot->>'sku'; IF NEW.estatus_liberacion IS NULL THEN NEW.estatus_liberacion:=CASE l.datos_calidad_snapshot->>'estado' WHEN 'liberada' THEN 'L' WHEN 'rechazada' THEN 'NC' ELSE 'C' END; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_imp_cinta_datos BEFORE INSERT OR UPDATE ON public.pesajes_cintas FOR EACH ROW EXECUTE FUNCTION public.imp_cinta_datos();
CREATE POLICY pc_imp_planta ON public.pesajes_cintas AS RESTRICTIVE FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.pesajes_cintas_lotes l WHERE l.id=lote_id));